Translate the following GNU C++ code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>

using namespace std;

long long C[777][777];

int r, c;
long long total;
long long min_diff = (long long)1e18, min_value = -1;

void explore_paths(long long x, long long y, int v1, int v2)
{
	long long diff = abs(x - y);
	if (min_diff <= 1 || diff - C[v1][r] * C[v2][r] >= min_diff)
		return;

  if (v1 == r - 1 && v2 == r - 1)
  {
    long long diff = abs(x - y); 
    if (diff < min_diff) {
      min_diff = diff;
      min_value = x;
    }
    return;
  }
	if (v1 >= r)
	{
    	long long delta1 = C[v1][r] - C[v1 - 1][r];
		long long sum2 = C[v2][r];
    	explore_paths(x, y + delta1 * sum2, v1 - 1, v2);
	}
	if (v2 >= r)
	{
		long long sum1 = C[v1][r];
		long long delta2 = C[v2][r] - C[v2 - 1][r];
		explore_paths(x + sum1 * delta2, y, v1, v2 - 1);
	}
}

char s[12345];
int cntA[12345], cntB[12345];
map<long long, long long> memo_map;

long long get_score(long long x, long long y, int v1, int v2)
{
	long long key = x * 10000 + v1 * 100 + v2;
	if (memo_map.count(key))
		return memo_map[key];

  long long &res = memo_map[key];
  long long diff = abs(x - y);
  if (diff - C[v1][r] * C[v2][r] > min_diff) {
    return res = 0;
  }
  if (v1 < r || v2 < r) {
    if (v1 >= cntA[v1 + v2] && v2 >= cntB[v1 + v2]) {
      int sum = v1 + v2;
      v1 -= cntA[sum];
      v2 -= cntB[sum];
      return res = C[v1 + v2][v1]; 
    }
    return res = 0;
  }
	res = 0;
	char c = s[v1 + v2 - 1];
	if (c != 'B')
	{
		long long delta1 = C[v1][r] - C[v1 - 1][r];
		long long sum2 = C[v2][r];
		res += get_score(x, y + delta1 * sum2, v1 - 1, v2);
	}
	if (c != 'A')
	{
		long long sum1 = C[v1][r];
		long long delta2 = C[v2][r] - C[v2 - 1][r];
		res += get_score(x + sum1 * delta2, y, v1, v2 - 1);
	}
	return res;
}

int main() {
  scanf("%d %d", &r, &c);
  for (int i = 0; i <= 2 * (r + c); i++) {
    for (int j = 0; j <= 2 * (r + c); j++) {
      if (j == 0) C[i][j] = 1; else
      if (i == 0) C[i][j] = 0;
      else C[i][j] = (C[i - 1][j] + C[i - 1][j - 1]);
    }
  }
  total = C[r + c][r] * C[r + c][r];
  {
    long long x = 0, y = 0;
    int v1 = r + c, v2 = r + c;
    while (v1 >= r && v2 >= r) {
      if (x > y) {
        long long delta1 = C[v1][r] - C[v1 - 1][r];
        long long sum2 = C[v2][r];
        y += delta1 * sum2;
        v1--;
      } else {
        long long sum1 = C[v1][r];
        long long delta2 = C[v2][r] - C[v2 - 1][r];
        x += sum1 * delta2;
        v2--;
      }
    }
    min_diff = abs(x - y);
  }
  explore_paths(0, 0, r + c, r + c);
  scanf("%s", s);
  cntA[0] = cntB[0] = 0;
  for (int i = 0; i < 2 * (r + c); i++) {
    cntA[i + 1] = cntA[i] + (s[i] == 'A');
    cntB[i + 1] = cntB[i] + (s[i] == 'B');
  }
  long long answer_score = get_score(0, 0, r + c, r + c);
  cout << answer_score << endl;
  return 0;
}
